/**
 * Allow-list sanitizer for the server's question-material HTML (TOPIK passages,
 * tables, guiding questions). That HTML is written by admins or generated by an
 * LLM, so it is not trusted: the session tokens live in localStorage, and a
 * single `<img onerror>` rendered through `dangerouslySetInnerHTML` could read
 * them.
 *
 * The content only ever uses simple text markup, so everything else is
 * removed: unknown elements are unwrapped (their text is kept), elements whose
 * content is code or media are dropped whole, and every attribute is stripped
 * except the table-span ones. Parsing uses a detached `DOMParser` document,
 * which never runs scripts or loads resources.
 */

const ALLOWED_TAGS = new Set([
  "p", "br", "div", "span",
  "strong", "b", "em", "i", "u", "s", "sub", "sup", "mark", "small",
  "ul", "ol", "li",
  "table", "caption", "thead", "tbody", "tfoot", "tr", "th", "td",
  "blockquote", "hr",
]);

/** Dropped with their content — keeping the text of these would show code. */
const DROPPED_TAGS = new Set([
  "script", "style", "template", "iframe", "frame", "frameset", "object", "embed",
  "noscript", "svg", "math", "link", "meta", "base", "form", "textarea", "select",
]);

const ALLOWED_ATTRS = new Set(["colspan", "rowspan"]);

function clean(node: Node): void {
  for (const child of Array.from(node.childNodes)) {
    if (child.nodeType === Node.COMMENT_NODE) {
      child.remove();
      continue;
    }
    if (child.nodeType !== Node.ELEMENT_NODE) continue;
    const el = child as Element;
    const tag = el.tagName.toLowerCase();
    if (DROPPED_TAGS.has(tag)) {
      el.remove();
      continue;
    }
    clean(el);
    if (!ALLOWED_TAGS.has(tag)) {
      el.replaceWith(...Array.from(el.childNodes));
      continue;
    }
    for (const attr of Array.from(el.attributes)) {
      if (!ALLOWED_ATTRS.has(attr.name.toLowerCase()) || !/^\d{1,3}$/.test(attr.value.trim())) {
        el.removeAttribute(attr.name);
      }
    }
  }
}

export function sanitizeHtml(html: string): string {
  const doc = new DOMParser().parseFromString(`<body>${html}</body>`, "text/html");
  clean(doc.body);
  return doc.body.innerHTML;
}
